    {
        threadReplyCounts = [];
        // Identify messages that have replies (messages with replies have other messages referencing them)
        var rootIds = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var rootId in rootIds)
