+.emoji-btn:hover {
+    background: #f0f0f0;
+}
+
+/* Message Input */
+.message-input {
+    display: flex;
+    gap: 8px;
+    padding: 12px 20px;
+    border-top: 1px solid #e0e0e0;
+    align-items: flex-end;
+}
+
+.message-input textarea {
+    flex: 1;
+    resize: none;
+    border: 1px solid #ddd;
+    border-radius: 8px;
+    padding: 10px 12px;
+    font-size: 0.9rem;
+    font-family: inherit;
+    outline: none;
+    transition: border-color 0.15s;
+}
+
+.message-input textarea:focus {
+    border-color: #1264a3;
+}
+
+.send-btn {
+    background: #007a5a;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 16px;
+    font-weight: 600;
+    cursor: pointer;
+    font-size: 0.9rem;
+    transition: background 0.15s;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #005e44;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #f9f9f9;
+    border-left: 1px solid #e0e0e0;
+    display: flex;
+    flex-direction: column;
+    overflow: hidden;
+}
+
+.thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 12px 16px;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+    color: #666;
+}
+
+.close-btn:hover {
+    background: #e0e0e0;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #e0e0e0;
+    background: #fff;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+.thread-reply {
+    padding: 8px 12px;
+    border-radius: 6px;
+    background: #fff;
+}
+
+/* Layout width adjustment when thread is open vs closed */
+.chat-layout.thread-open .message-area {
+    width: 55%;
+    flex: none;
+}
+
+.chat-layout:not(.thread-open) .message-area {
+    width: 80%;
+    flex: 1;
+}
+

